  {
    "entity_type": "kpi",
    "id": "bacda60e-2f65-4962-b3a9-387bcbc2d2cd",
    "kpi_name": "TOLS Category Signal Statistics",
    "kpi_alias": null,
    "relevant_for_designations": null,
    "creation_mode": "sql_playground",
    "kpi_description": "Groups signals by TOLS Category (Low/Medium/High) and computes per-category metrics: signal count, average Bandwidth-to-Frequency Ratio (BFR), and anomaly score dispersion (variance formula AVG(x²)−AVG(x)², NOT standard deviation with SQRT). TOLS = TechSigProb×(1−NatSrcProb)×SigUnique×(0.5+AnomScore/10). BFR = BwHz/(CenterFreqMhz×1000000). Category thresholds: Low <0.25, Medium <0.75, High ≥0.75. Requires JOIN between signals and signalprobabilities on signalregistry=signalref. Note: AnomScore column is declared INTEGER(53) but stores REAL 0.00-0.99 values via SQLite dynamic typing.",
    "calculation_logic": null,
    "sql_query": "SELECT CASE WHEN p.techsigprob * (1.0 - p.natsrcprob) * p.sigunique * (0.5 + p.anomscore / 10.0) < 0.25 THEN 'Low' WHEN p.techsigprob * (1.0 - p.natsrcprob) * p.sigunique * (0.5 + p.anomscore / 10.0) < 0.75 THEN 'Medium' ELSE 'High' END AS tol_category, COUNT(*) AS signal_count, AVG(s.bwhz / (s.centerfreqmhz * 1000000.0)) AS avg_bfr, AVG(p.anomscore * p.anomscore) - AVG(p.anomscore) * AVG(p.anomscore) AS anomaly_stddev FROM livesql_alien_main_signals s JOIN livesql_alien_main_signalprobabilities p ON s.signalregistry = p.signalref GROUP BY tol_category AS tols_category_stats;",
    "set_values": null,
    "creator_user_id": "ee7fc1546821ebfae8c05438",
