  {
    "entity_type": "table_data",
    "id": "45ca0f55-4773-4222-a6c6-4e44aa0faf7a",
    "database_id": "4d2a2455-cca4-4574-9833-66320b3a958a",
    "table_name": "main.signalprobabilities",
    "table_description": "Stores probability assessment scores for each detected signal. One row = one signal's probability profile, identified by SignalRef (PK, FK → Signals.SignalRegistry). Key columns for TOLS/BFR analysis: TechSigProb (real, 0.00–0.99), NatSrcProb (real, 0.00–1.00), SigUnique (real, 0.00–0.99), AnomScore (integer(53) declared but stores REAL 0.00–0.99 — SQLite dynamic typing). Together with Signals.BwHz and Signals.CenterFreqMhz, these compute TOLS = TechSigProb × (1 − NatSrcProb) × SigUnique × (0.5 + AnomScore/10) and BFR = BwHz/(CenterFreqMhz × 1000000). Also contains: FalsePosProb, SimIndex, CorrScore, BioSigProb, ArtSrcProb.",
    "creator_user_id": "ee7fc1546821ebfae8c05438"
  },
  {
    "entity_type": "table_data",
    "id": "a3b0e760-1067-4008-bed8-55f061c0a055",
    "database_id": "4d2a2455-cca4-4574-9833-66320b3a958a",
    "table_name": "main.signals",
    "table_description": "Stores detected signal records. One row = one signal detection event, identified by SignalRegistry (PK). Key columns for TOLS/BFR analysis: BwHz (real, bandwidth in Hz, 0.44–991.65), CenterFreqMhz (real, center frequency in MHz, 412.50–99399.86) — together compute BFR = BwHz/(CenterFreqMhz × 1000000). Also: freqmhz (frequency in MHz), sigdursec (signal duration), signalclass (Narrowband/Broadband/Modulated/Continuous/Pulsed), snrratio (SNR ratio), noisefloordbm (noise floor in dBm). Has telescref (FK → telescopes.Telescregistry) linking each signal to the telescope that detected it. Joins to SignalProbabilities via SignalRegistry = SignalRef for TOLS = TechSigProb × (1 − NatSrcProb) × SigUnique × (0.5 + AnomScore/10) computation.",
    "creator_user_id": "ee7fc1546821ebfae8c05438"
  },
  {
    "entity_type": "table_data",
    "id": "d40ed75c-1a40-4a36-8d53-17fc1d9b96c3",
    "database_id": "4d2a2455-cca4-4574-9833-66320b3a958a",
    "table_name": "main.telescopes",
    "table_description": "Bridge table connecting signals to observatories. One row = one telescope, identified by telescregistry (PK). Contains observstation (FK → observatories.observstation) linking each telescope to its observatory station. Signals join to telescopes via signals.telescref = telescopes.telescregistry, and telescopes join to observatories via telescopes.observstation = observatories.observstation. This3-table join (Signals→Telescopes→Observatories) is required to access WeathProfile for weather-condition-based signal analysis.",
    "creator_user_id": "ee7fc1546821ebfae8c05438"
  }
